'use strict';
const fs=require('fs'),path=require('path'),zlib=require('zlib');
const root=path.resolve(__dirname,'../..');
const entries=JSON.parse(zlib.inflateSync(Buffer.from('','base64')));
for(const entry of entries){if(!entry.path.startsWith('SOFIA_APP/')||entry.path.split('/').includes('..'))throw Error('Unsafe path');const p=path.join(root,entry.path);fs.mkdirSync(path.dirname(p),{recursive:true});fs.writeFileSync(p,entry.content);}
console.log('Applied reviewed 0.3.33 changes',entries.length);
